<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Repositories\DatabaseFirewallRepository;use App\Security\Auth;use App\Services\DatabaseFirewallService;use Throwable;
final readonly class DatabaseFirewallController{public function __construct(private View $view,private DatabaseFirewallRepository $repo,private DatabaseFirewallService $service,private Csrf $csrf){}public function index(Request $r):void{$this->allow();$this->view->render('security/database-firewall',['title'=>'Firewall de base de datos','rules'=>$this->repo->rules(),'servers'=>$this->repo->servers(),'runs'=>$this->repo->runs(),'csrf'=>$this->csrf]);}public function add(Request $r):void{$this->allow();$this->run(fn()=>$this->service->add($r->int('server_id'),$r->string('ip_kind')));}public function remove(Request $r):void{$this->allow();$this->run(fn()=>$this->service->remove($r->int('id')));}public function apply(Request $r):void{$this->allow();$this->run(fn()=>$this->service->apply());}private function run(callable $fn):never{try{$fn();Response::redirect('/security/database');}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}}private function allow():void{if(!Auth::can('database.firewall.manage')){http_response_code(403);exit('Sin permiso');}}}
